    "        print(\"Хи квадрат равен : \", Xi22 )\n",
    "    else:\n",
    "        print(\"Error\")\n",
    "    if (g3.Xi_homogeneous < sp.stats.chi2.ppf(1 - 0.05, g3.loops + 1) ):\n",
